// bfsFrom returns the sum of distances from one node, in O(n). Used as a cheap
// oracle on the big trees: doing it for every node is the O(n^2) approach the
// sizes below rule out.
func bfsFrom(n int, adj [][]int32, src int) int {
	dist := make([]int32, n)
	for i := range dist {
		dist[i] = -1
	}
	dist[src] = 0
	q := make([]int32, 1, n)
	q[0] = int32(src)
	total := 0
	for i := 0; i < len(q); i++ {
		u := q[i]
		for _, v := range adj[u] {
			if dist[v] < 0 {
				dist[v] = dist[u] + 1
				total += int(dist[v])
				q = append(q, v)
			}
		}
	}
	return total
}

func adjacency(n int, edges [][]int) [][]int32 {
	deg := make([]int, n)
	for _, e := range edges {
		deg[e[0]]++
		deg[e[1]]++
	}
	adj := make([][]int32, n)
	for i := range adj {
		adj[i] = make([]int32, 0, deg[i])
