// binomialRow returns C(n,0..n) mod p, where p is a prime greater than n.
func binomialRow(n int, p int) []int {
	row := make([]int, n+1)
	row[0] = 1 % p
	// inv[k] is the modular inverse of k, built from p = (p/k)*k + p%k.
	inv := make([]int, n+2)
	if n >= 1 {
		inv[1] = 1 % p
	}
	for k := 2; k <= n; k++ {
		inv[k] = (p - (p/k)*inv[p%k]%p) % p
	}
	for k := 1; k <= n; k++ {
		row[k] = row[k-1] * ((n - k + 1) % p) % p * inv[k] % p
	}
	return row
}

