import (
	"math/rand"
	"sort"
	"testing"
)

func cross2(o, a, b []int) int {
	return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
}

func lessPoint(a, b []int) bool {
	if a[0] != b[0] {
		return a[0] < b[0]
	}
	return a[1] < b[1]
}

func distinctSorted(points [][]int) [][]int {
	cp := make([][]int, len(points))
	copy(cp, points)
	sort.Slice(cp, func(i, j int) bool { return lessPoint(cp[i], cp[j]) })
	out := make([][]int, 0, len(cp))
	for _, p := range cp {
		if n := len(out); n == 0 || out[n-1][0] != p[0] || out[n-1][1] != p[1] {
			out = append(out, p)
		}
	}
	return out
}

func samePoints(got, want [][]int) bool {
	if len(got) != len(want) {
		return false
	}
	for i := range got {
		if len(got[i]) != 2 || got[i][0] != want[i][0] || got[i][1] != want[i][1] {
			return false
		}
	}
	return true
}

// checkHull is a full oracle for the general case: the answer must use input
// points, turn strictly left everywhere, start at the smallest point, and
// contain every input point. Only the hull satisfies all four.
func checkHull(t *testing.T, points, hull [][]int) {
	t.Helper()
	d := distinctSorted(points)
	if len(hull) < 3 {
		t.Fatalf("hull has %d vertices for %d distinct points", len(hull), len(d))
	}
	if hull[0][0] != d[0][0] || hull[0][1] != d[0][1] {
		t.Fatalf("hull starts at (%d,%d), want the smallest point (%d,%d)", hull[0][0], hull[0][1], d[0][0], d[0][1])
	}
	in := make(map[[2]int]bool, len(d))
	for _, p := range d {
		in[[2]int{p[0], p[1]}] = true
	}
	seen := make(map[[2]int]bool, len(hull))
	for _, p := range hull {
		k := [2]int{p[0], p[1]}
		if !in[k] {
			t.Fatalf("hull vertex (%d,%d) is not an input point", p[0], p[1])
		}
		if seen[k] {
			t.Fatalf("hull repeats (%d,%d)", p[0], p[1])
		}
		seen[k] = true
	}
	n := len(hull)
	for i := range hull {
		o, a, b := hull[i], hull[(i+1)%n], hull[(i+2)%n]
		if c := cross2(o, a, b); c <= 0 {
			t.Fatalf("turn at (%d,%d) is %d, want a strict left turn", a[0], a[1], c)
		}
	}
	for _, p := range d {
		for i := range hull {
			if cross2(hull[i], hull[(i+1)%n], p) < 0 {
				t.Fatalf("point (%d,%d) is outside edge %d of the hull", p[0], p[1], i)
			}
		}
	}
}

